import type { PointerEvent as ReactPointerEvent, RefObject } from "react";
import type { LayerSeparatorSelection } from "../LayerSeparator.types";

type SelectionStageProps = {
  stageRef: RefObject<HTMLDivElement | null>;
  imageUrl: string;
  imageAlt: string;
  aspectRatio: number;
  selections: LayerSeparatorSelection[];
  draft: LayerSeparatorSelection | null;
  hint: string;
  onPointerDown: (event: ReactPointerEvent<HTMLDivElement>) => void;
  onPointerMove: (event: ReactPointerEvent<HTMLDivElement>) => void;
  onPointerUp: (event: ReactPointerEvent<HTMLDivElement>) => void;
  onPointerCancel: () => void;
};

export default function SelectionStage({
  stageRef,
  imageUrl,
  imageAlt,
  aspectRatio,
  selections,
  draft,
  hint,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
}: SelectionStageProps) {
  return (
    <div
      ref={stageRef}
      className="layer-separator__stage layer-separator__selection-stage"
      style={{ aspectRatio }}
    >
      <img src={imageUrl} alt={imageAlt} draggable={false} />
      <div
        className="layer-separator__selection-surface"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerCancel}
      >
        {[...selections, ...(draft ? [draft] : [])].map((selection, index) => {
          const left = Math.min(selection.x1, selection.x2);
          const top = Math.min(selection.y1, selection.y2);
          const width = Math.abs(selection.x2 - selection.x1);
          const height = Math.abs(selection.y2 - selection.y1);
          return (
            <div
              key={selection.id}
              className="layer-separator__selection-box"
              style={{
                left: `${left * 100}%`,
                top: `${top * 100}%`,
                width: `${width * 100}%`,
                height: `${height * 100}%`,
              }}
            >
              <span className="layer-separator__selection-number">{index + 1}</span>
              <i data-corner="tl" /><i data-corner="tr" />
              <i data-corner="bl" /><i data-corner="br" />
            </div>
          );
        })}
        {selections.length === 0 && !draft ? (
          <p className="layer-separator__selection-hint">{hint}</p>
        ) : null}
      </div>
    </div>
  );
}

import { Button } from "../../motion/button/base";
import {
  FlipHorizontal2,
  FlipVertical2,
  RotateCw,
} from "lucide-react";
import type { PointerEvent as ReactPointerEvent } from "react";
import type {
  LayerSeparatorAsset,
  LayerSeparatorResult,
  LayerSeparatorTransform,
} from "../LayerSeparator.types";
import { normalizeTransform } from "../LayerSeparator.utils";

type CompositionStageProps = {
  result: LayerSeparatorResult;
  aspectRatio: number;
  backgroundLabel: string;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  onChange: (id: string, transform: LayerSeparatorTransform) => void;
};

function layerFrame(layer: LayerSeparatorAsset) {
  const transform = normalizeTransform(layer.transform);
  const bounds = layer.contentBounds ?? { x: 0, y: 0, width: 1, height: 1 };
  return {
    x: transform.x + bounds.x * transform.width,
    y: transform.y + bounds.y * transform.height,
    width: bounds.width * transform.width,
    height: bounds.height * transform.height,
  };
}

export default function CompositionStage({
  result,
  aspectRatio,
  backgroundLabel,
  selectedId,
  onSelect,
  onChange,
}: CompositionStageProps) {
  const beginMove = (event: ReactPointerEvent, layer: LayerSeparatorAsset) => {
    event.preventDefault();
    event.stopPropagation();
    const target = event.currentTarget as HTMLElement;
    target.setPointerCapture(event.pointerId);
    const stage = target.closest<HTMLElement>(".layer-separator__composition-stage");
    if (!stage) return;
    const start = { x: event.clientX, y: event.clientY };
    const initial = normalizeTransform(layer.transform);
    onSelect(layer.id);

    const move = (pointerEvent: PointerEvent) => {
      const rect = stage.getBoundingClientRect();
      onChange(layer.id, {
        ...initial,
        x: initial.x + (pointerEvent.clientX - start.x) / rect.width,
        y: initial.y + (pointerEvent.clientY - start.y) / rect.height,
      });
    };
    const stop = () => {
      target.removeEventListener("pointermove", move);
      target.removeEventListener("pointerup", stop);
      target.removeEventListener("pointercancel", stop);
    };
    target.addEventListener("pointermove", move);
    target.addEventListener("pointerup", stop);
    target.addEventListener("pointercancel", stop);
  };

  return (
    <div
      className="layer-separator__stage layer-separator__composition-stage"
      style={{ aspectRatio }}
      onPointerDown={() => onSelect(null)}
    >
      <img className="layer-separator__background" src={result.background.url} alt="" draggable={false} />
      <span className="layer-separator__background-label">{backgroundLabel}</span>
      {result.layers.map((layer, index) => {
        const transform = normalizeTransform(layer.transform);
        const bounds = layer.contentBounds ?? { x: 0, y: 0, width: 1, height: 1 };
        const frame = layerFrame(layer);
        if (!transform.visible) return null;
        const selected = selectedId === layer.id;
        return (
          <div key={layer.id}>
            <div
              className="layer-separator__layer-image"
              style={{
                left: `${transform.x * 100}%`,
                top: `${transform.y * 100}%`,
                width: `${transform.width * 100}%`,
                height: `${transform.height * 100}%`,
                transform: `rotate(${transform.rotation}deg) scale(${transform.flipX ? -1 : 1}, ${transform.flipY ? -1 : 1})`,
                transformOrigin: `${(bounds.x + bounds.width / 2) * 100}% ${(bounds.y + bounds.height / 2) * 100}%`,
              }}
            >
              <img
                src={layer.url}
                alt=""
                draggable={false}
              />
            </div>
            <button
              type="button"
              className={["layer-separator__layer-hitbox", selected ? "is-selected" : ""].join(" ")}
              style={{
                left: `${frame.x * 100}%`,
                top: `${frame.y * 100}%`,
                width: `${frame.width * 100}%`,
                height: `${frame.height * 100}%`,
                transform: `rotate(${transform.rotation}deg)`,
              }}
              aria-label={layer.name ?? `Layer ${index + 1}`}
              onPointerDown={(event) => beginMove(event, layer)}
            />
            {selected ? (
              <div
                className="layer-separator__object-toolbar"
                onPointerDown={(event) => event.stopPropagation()}
              >
                <Button variant="ghost" size="icon" type="button" aria-label="Rotate layer" onClick={() => onChange(layer.id, { ...transform, rotation: (transform.rotation + 90) % 360 })}><RotateCw size={15} /></Button>
                <Button variant="ghost" size="icon" type="button" aria-label="Flip layer horizontally" onClick={() => onChange(layer.id, { ...transform, flipX: !transform.flipX })}><FlipHorizontal2 size={15} /></Button>
                <Button variant="ghost" size="icon" type="button" aria-label="Flip layer vertically" onClick={() => onChange(layer.id, { ...transform, flipY: !transform.flipY })}><FlipVertical2 size={15} /></Button>
              </div>
            ) : null}
          </div>
        );
      })}
    </div>
  );
}

"use client";
// beui.dev/components/motion/range-slider

import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react";
import { useEffect, useLayoutEffect, useState } from "react";

import { SPRING_GLIDE } from "./lib/ease";
import { type SliderOptions, useSlider } from "./lib/hooks/use-slider";
import { TOUCH_GESTURE_CLASS } from "./lib/touch";
import { cn } from "./lib/utils";

// Bouncy grab feedback for the thumb scale only.
const SPRING_BOUNCY = { type: "spring", stiffness: 500, damping: 14, mass: 0.7 } as const;

export interface RangeSliderProps extends SliderOptions {
  /** Render a tick dot at each step. */
  showTicks?: boolean;
  className?: string;
}

export function RangeSlider({ showTicks = true, className, ...options }: RangeSliderProps) {
  const reduce = useReducedMotion();
  const { percent, dragging, min, max, step, trackProps, sliderProps } = useSlider(options);
  const [trackWidth, setTrackWidth] = useState(292);
  useLayoutEffect(() => {
    const track = trackProps.ref.current;
    if (!track) return;
    const measure = () => {
      const width = track.getBoundingClientRect().width;
      if (width > 0) setTrackWidth(width);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(track);
    return () => observer.disconnect();
  }, [trackProps.ref]);

  // Spring-smoothed position drives both the thumb and the fill.
  const target = useMotionValue(percent);
  useEffect(() => {
    target.set(percent);
  }, [percent, target]);
  const smooth = useSpring(target, SPRING_GLIDE);
  const pos = reduce ? target : smooth;
  const thumbX = useTransform(pos, (p) => 8 + Math.max(0, trackWidth - 20) * p / 100);
  // Match InlineSlider: the 4px handle starts 8px inside the track, and
  // the rounded fill extends 8px past its left edge. Translate a full-size
  // fill inside the 2px inset clip so its corner never stretches.
  const fillX = useTransform(pos, (p) => p >= 100
    ? "0%"
    : `calc(${p - 100}% + ${14 - 0.16 * p}px)`);

  // Floor rather than round, so a range the step does not divide (0 to 10 by 4)
  // stops its dots at the last whole step instead of drawing one past max.
  // toFixed comes first because 0.3/0.1 is 2.9999999999999996, which would
  // floor to 2 and drop the last dot.
  const steps = Math.floor(Number(((max - min) / step).toFixed(6)));
  const ticks =
    showTicks && steps > 0 && steps <= 50
      ? Array.from({ length: steps + 1 }, (_, i) => Number((min + i * step).toFixed(6)))
      : [];

  return (
    <div
      {...trackProps}
      className={cn(
        "relative flex h-10 w-full touch-none items-center overflow-hidden rounded-lg bg-muted",
        TOUCH_GESTURE_CLASS,
        options.disabled
          ? "pointer-events-none opacity-50"
          : "cursor-grab active:cursor-grabbing",
        className,
      )}
    >
      <div aria-hidden="true" className="pointer-events-none absolute inset-x-[2px] inset-y-0 overflow-hidden rounded-lg">
        <motion.div className="absolute inset-0 rounded-lg bg-foreground/15" style={{ x: fillX }} />
      </div>

      {/* Tick centres follow the same inset path as the handle centre. */}
      <div className="pointer-events-none absolute inset-x-[10px] inset-y-0">
        {ticks.map((t) => {
          const tp = ((t - min) / (max - min)) * 100;
          return (
            <span
              key={t}
              className="absolute top-1/2 size-1 -translate-x-1/2 -translate-y-1/2 rounded-full bg-foreground/25"
              style={{ left: `${tp}%` }}
            />
          );
        })}
      </div>

      {/* Keep the handle inside the rounded progress fill at both ends. */}
      <motion.div
        {...sliderProps}
        animate={reduce ? undefined : { scaleY: dragging ? 1.35 : 1 }}
        transition={SPRING_BOUNCY}
        className="absolute left-0 top-1/2 h-6 w-1 rounded-full bg-foreground outline-none ring-inset ring-foreground/30 focus-visible:ring-4"
        style={{ x: thumbX, y: "-50%" }}
      />
    </div>
  );
}

